"""Agent runner — the background loop that ticks every enabled agent once
per minute.

Discovery mirrors the skills registry: every non-underscore `.py` file in
`agents/` is imported and the single `Agent` subclass inside is
instantiated.  Runs in a daemon thread so it doesn't block shutdown.
"""

from __future__ import annotations

import importlib
import pkgutil
import threading
import time
from datetime import datetime
from typing import Callable, Optional

import agents  # package — for walk_packages
from agents._base import Agent, AgentContext
from utils.logger import get_logger

logger = get_logger(__name__)

TICK_INTERVAL_SEC = 30  # how often we check whether any agent should run


class AgentRunner:
    def __init__(self, speak: Callable[[str], None]):
        self._agents: list[Agent] = _discover_agents()
        # Build context once — shared across ticks
        from memory import get_memory
        self._ctx = AgentContext(speak=speak, memory=get_memory())
        self._thread: Optional[threading.Thread] = None
        self._running = False
        enabled = [a for a in self._agents if not a.disabled_by_default]
        logger.info(
            f"AgentRunner loaded: {len(enabled)}/{len(self._agents)} agents "
            f"({', '.join(a.name for a in enabled)})"
        )

    # ── Lifecycle ───────────────────────────────────────────────────────────

    def start(self):
        if self._running:
            return
        self._running = True
        self._thread = threading.Thread(target=self._loop, daemon=True, name="jarvis-agents")
        self._thread.start()

    def stop(self):
        self._running = False
        if self._thread:
            self._thread.join(timeout=3)

    # ── Main loop ───────────────────────────────────────────────────────────

    def _loop(self):
        while self._running:
            try:
                self._tick_once()
            except Exception as e:
                logger.error(f"Agent tick error: {e}", exc_info=True)
            # Sleep in small slices so stop() is responsive
            slept = 0
            while self._running and slept < TICK_INTERVAL_SEC:
                time.sleep(0.5)
                slept += 0.5

    def _tick_once(self):
        now = datetime.now()
        for agent in self._agents:
            if agent.disabled_by_default:
                continue
            try:
                if not agent.should_run(now, self._ctx):
                    continue
            except Exception as e:
                logger.error(f"Agent {agent.name}.should_run() raised: {e}")
                continue
            # Fire in its own thread so one slow agent doesn't block the others
            threading.Thread(
                target=self._fire,
                args=(agent,),
                daemon=True,
                name=f"jarvis-agent-{agent.name}",
            ).start()

    def _fire(self, agent: Agent):
        logger.info(f"Firing agent: {agent.name}")
        try:
            agent.tick(self._ctx)
        except Exception as e:
            logger.error(f"Agent {agent.name}.tick() failed: {e}", exc_info=True)


# ── Discovery ───────────────────────────────────────────────────────────────

def _discover_agents() -> list[Agent]:
    found: list[Agent] = []
    for _, mod_name, is_pkg in pkgutil.iter_modules(agents.__path__):
        if is_pkg or mod_name.startswith("_"):
            continue
        full = f"agents.{mod_name}"
        try:
            module = importlib.import_module(full)
        except Exception as e:
            logger.error(f"Agent import failed — {full}: {e}")
            continue
        agent_classes = [
            obj for obj in vars(module).values()
            if isinstance(obj, type)
            and issubclass(obj, Agent)
            and obj is not Agent
            and obj.__module__ == full
        ]
        if not agent_classes:
            continue
        try:
            found.append(agent_classes[0]())
        except Exception as e:
            logger.error(f"Agent instantiation failed — {full}: {e}")
    return found


# ── Singleton ───────────────────────────────────────────────────────────────

_runner: Optional[AgentRunner] = None


def get_agent_runner(speak: Optional[Callable[[str], None]] = None) -> AgentRunner:
    """First call wires in the `speak` callable.  Subsequent calls ignore it."""
    global _runner
    if _runner is None:
        if speak is None:
            raise RuntimeError(
                "First get_agent_runner() call must provide a `speak` callable."
            )
        _runner = AgentRunner(speak=speak)
    return _runner
